 "concepts": [
  {
   "aliases": [
    "q",
    "bandwidth",
    "resonance width"
   ],
   "causalExplanation": "A low Q spreads the change across many frequencies so it reads as overall tone; a high Q affects a narrow region so it reads as removing or adding one specific ringing note.",
   "commonMisunderstanding": "That a higher Q is 'more precise' and therefore better. Narrow cuts can sound worse on moving material than a gentle broad move.",
   "domains": [
    "eqAndFiltering"
   ],
   "id": "concept.q",
   "practicalExample": "Searching for a resonance uses a high-ish Q boost; the final corrective cut usually uses a gentler Q and much less gain.",
   "relatedProcedureIDs": [
    "tutor.vocal.channel-eq-resonance-search.v1"
   ],
   "reviewState": "reviewed",
   "simpleExplanation": "Q is how wide or narrow an EQ band is.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Q is the ratio of centre frequency to bandwidth. Higher Q means a narrower affected region for the same centre frequency. Very high Q cuts can sound unnatural on sustained material because they track a narrow region that the music moves through.",
   "term": "Q",
   "version": "1.0",
   "whereItMatters": [
    "Finding and reducing a resonance",
    "Broad tonal balancing"
   ]
  },
  {
   "aliases": [
    "threshold"
   ],
   "causalExplanation": "Signal above the threshold gets reduced; signal below it passes untouched. Lowering the threshold means more of the performance is being acted on.",
   "commonMisunderstanding": "That a lower threshold always means more control. Below a point it mostly removes the natural level differences that make a performance feel alive.",
   "domains": [
    "compression"
   ],
   "id": "concept.threshold",
   "practicalExample": "If only the loudest words are being controlled, the threshold is high; if the whole phrase is being squeezed, it is low.",
   "relatedProcedureIDs": [],
   "reviewState": "reviewed",
   "simpleExplanation": "Threshold is the level where a compressor starts working.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Threshold interacts with ratio and knee to define the static curve. With a soft knee, gain reduction begins gradually near the threshold rather than switching on at a point.",
   "term": "Threshold",
   "version": "1.0",
   "whereItMatters": [
    "Vocal level consistency",
    "Drum bus glue"
   ]
  },
  {
   "aliases": [
    "ratio"
   ],
   "causalExplanation": "A 2:1 ratio halves how far the signal exceeds the threshold; a 10:1 ratio nearly stops it exceeding at all, which reads as limiting rather than compression.",
   "commonMisunderstanding": "That a high ratio is 'stronger compression'. Ratio and threshold together determine how much is actually happening.",
   "domains": [
    "compression"
   ],
   "id": "concept.ratio",
   "practicalExample": "Gentle vocal control often sits near 2:1 to 4:1; catching occasional peaks may use a much higher ratio with a high threshold.",
   "relatedProcedureIDs": [],
   "reviewState": "reviewed",
   "simpleExplanation": "Ratio is how strongly the compressor reduces what goes above the threshold.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Ratio defines the slope of the static curve above the threshold. High ratios with fast attack behave as limiters and can dull transients; low ratios with more gain reduction often sound more natural than high ratios with less.",
   "term": "Ratio",
   "version": "1.0",
   "whereItMatters": [
    "Vocal dynamics",
    "Peak control"
   ]
  },
  {
   "aliases": [
    "attack",
    "attack time"
   ],
   "causalExplanation": "A fast attack catches the very start of a note, which can reduce its punch. A slower attack lets the initial transient through and compresses the body, which usually keeps more perceived impact.",
   "commonMisunderstanding": "That fast attack means 'tighter'. On transient material it often means duller.",
   "domains": [
    "compression",
    "transientShaping"
   ],
   "id": "concept.attack",
   "practicalExample": "On a snare, a slower attack tends to preserve the crack; a very fast attack can make it sound flatter.",
   "relatedProcedureIDs": [],
   "reviewState": "reviewed",
   "simpleExplanation": "Attack is how quickly the compressor reacts once the signal passes the threshold.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Attack sets the detector/gain-computer time constant for increasing gain reduction. Its audible effect depends on the material's transient density; on sustained sources the distinction narrows considerably.",
   "term": "Attack",
   "version": "1.0",
   "whereItMatters": [
    "Drum punch",
    "Vocal control"
   ]
  },
  {
   "aliases": [
    "release",
    "release time"
   ],
   "causalExplanation": "Too fast can cause audible pumping or distortion on low frequencies; too slow can leave the signal held down through quieter passages so the performance loses life.",
   "commonMisunderstanding": "That release is inaudible because it happens after the loud part. It strongly shapes the perceived groove and sustain.",
   "domains": [
    "compression"
   ],
   "id": "concept.release",
   "practicalExample": "If the vocal seems to 'breathe' up between words in a distracting way, the release is likely too fast for that phrase.",
   "relatedProcedureIDs": [],
   "reviewState": "reviewed",
   "simpleExplanation": "Release is how quickly the compressor stops working once the signal falls back.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Release sets the time constant for recovering gain reduction. Program-dependent or auto release modes vary this with material. Release interacting with musical tempo is why compression can sound rhythmic.",
   "term": "Release",
   "version": "1.0",
   "whereItMatters": [
    "Vocal consistency",
    "Bus compression feel"
   ]
  },
  {
   "aliases": [
    "parallel compression",
    "new york compression",
    "blend compression"
   ],
   "causalExplanation": "Because the untouched signal remains, the transients and dynamics survive while the compressed copy raises the quiet detail. That is why it can add density without the flattening that the same compression would cause in series.",
   "commonMisunderstanding": "That it is simply 'more compression'. Its point is keeping the uncompressed dynamics present.",
   "domains": [
    "parallelProcessing",
    "compression"
   ],
   "id": "concept.parallel-compression",
   "practicalExample": "A drum bus where the heavily compressed copy is blended in until the room and sustain come up, then backed off.",
   "relatedProcedureIDs": [],
   "reviewState": "reviewed",
   "simpleExplanation": "Parallel compression blends a heavily compressed copy under the original instead of replacing it.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Implemented with a send to a bus or a plug-in mix control. Timing and phase must match between paths; a latency mismatch between parallel paths causes comb filtering rather than reinforcement.",
   "term": "Parallel compression",
   "version": "1.0",
   "whereItMatters": [
    "Drum density",
    "Vocal presence without squashing"
   ]
  },
  {
   "aliases": [
    "pre-delay",
    "predelay"
   ],
   "causalExplanation": "A longer gap lets the direct sound be heard clearly before the reverb arrives, so the source can stay up front while still sitting in a space. A very short pre-delay merges the two and tends to push the source backwards.",
   "commonMisunderstanding": "That pre-delay is a mix control. It changes perceived distance and clarity, not just the amount of effect.",
   "domains": [
    "preDelay",
    "reverb",
    "depth"
   ],
   "id": "concept.pre-delay",
   "practicalExample": "A vocal that disappears when reverb is added often improves with more pre-delay rather than less reverb.",
   "relatedProcedureIDs": [],
   "reviewState": "reviewed",
   "simpleExplanation": "Pre-delay is the gap between the dry sound and the start of its reverb.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Pre-delay corresponds to the time before early reflections in a real space, which relates to source and boundary distance. It interacts with reverb time and early-reflection level in determining perceived distance.",
   "term": "Pre-delay",
   "version": "1.0",
   "whereItMatters": [
    "Vocal depth",
    "Keeping a source forward in a large space"
   ]
  },
  {
   "aliases": [
    "phase cancellation",
    "phase",
    "polarity",
    "comb filtering"
   ],
   "causalExplanation": "When two copies of similar audio are offset in time or inverted in polarity, some frequencies reinforce and others subtract. The result is usually a hollow or thin tone that gets worse when the mix is summed to mono.",
   "commonMisunderstanding": "That phase problems only come from mistakes. Deliberate width techniques can create them too.",
   "domains": [
    "polarityAndPhase",
    "monoCompatibility"
   ],
   "id": "concept.phase-cancellation",
   "practicalExample": "A mix that sounds wide and full in stereo but thin and hollow in mono usually has phase-related side content.",
   "relatedProcedureIDs": [],
   "reviewState": "reviewed",
   "simpleExplanation": "Phase cancellation is when two similar signals partly cancel each other and the sound thins out.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Time offsets create frequency-dependent comb filtering with notches at regular intervals; polarity inversion is a broadband sign flip. Multi-microphone capture, doubled parts, and wide stereo processing are common causes.",
   "term": "Phase cancellation",
   "version": "1.0",
   "whereItMatters": [
    "Mono checks",
    "Multi-mic recording",
    "Stereo widening"
   ]
  },
  {
   "aliases": [
    "level matching",
    "level-matched",
    "gain matching"
   ],
   "causalExplanation": "Small level differences bias preference judgments, so an A/B that is not level matched mostly measures which version is louder rather than which is better.",
   "commonMisunderstanding": "That the difference is obvious enough to ignore level. It rarely is.",
   "domains": [
    "comparisonBias",
    "listeningLevel"
   ],
   "id": "concept.level-matched-comparison",
   "practicalExample": "Before deciding whether a compressor helped, match the bypassed and active levels and judge the character rather than the volume.",
   "relatedProcedureIDs": [
    "tutor.vocal.level-matched-bypass-comparison.v1"
   ],
   "reviewState": "reviewed",
   "simpleExplanation": "Compare two versions at the same loudness, because louder almost always seems better.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Loudness bias is well documented in listening-test methodology; differences of around a decibel can flip preference. Matching by ear is approximate but removes most of the effect.",
   "term": "Level-matched comparison",
   "version": "1.0",
   "whereItMatters": [
    "Every processing decision",
    "Master comparisons"
   ]
  },
  {
   "aliases": [
    "masking",
    "masked",
    "fighting"
   ],
   "causalExplanation": "Two sources sharing a frequency region and a moment in time compete for the same perceptual space, so raising one tends to bury the other. Fixing it usually means giving them different ranges, different moments, or different levels, not just boosting the quieter one.",
   "commonMisunderstanding": "That masking is fixed by EQ alone. Arrangement and level often matter more.",
   "domains": [
    "masking",
    "balance"
   ],
   "id": "concept.masking",
   "practicalExample": "Kick and bass that each sound fine alone but muddy together are usually competing in the same low band.",
   "relatedProcedureIDs": [],
   "reviewState": "reviewed",
   "simpleExplanation": "Masking is when one sound makes another harder to hear because they occupy the same range.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Masking is frequency- and level-dependent and is strongest for nearby frequencies. Arrangement choices, register allocation, and timing separation often solve masking more cleanly than corrective EQ.",
   "term": "Masking",
   "version": "1.0",
   "whereItMatters": [
    "Kick and bass",
    "Vocal versus dense arrangement"
   ]
  },
  {
   "aliases": [
    "wet",
    "dry",
    "mix control",
    "blend"
   ],
   "causalExplanation": "Blending keeps the original character present while the processed version adds its effect. Whether to blend inside a plug-in or on a separate bus changes what else you can do to the wet path.",
   "commonMisunderstanding": "That a mix knob and a send are equivalent. They allow different downstream control.",
   "domains": [
    "wetDryTopology"
   ],
   "id": "concept.wet-dry",
   "practicalExample": "A reverb on a send lets you EQ only the reverb; the same reverb as an insert with a mix knob does not.",
   "relatedProcedureIDs": [],
   "reviewState": "reviewed",
   "simpleExplanation": "Wet is the processed signal, dry is the original, and the blend sets how much of each you hear.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "An insert mix control and a send/return topology differ: the send path can be processed independently (filtered, compressed, delayed) while an insert blend cannot. Latency compensation matters when the paths are separate.",
   "term": "Wet/dry",
   "version": "1.0",
   "whereItMatters": [
    "Reverb and delay routing",
    "Parallel processing"
   ]
  },
  {
   "aliases": [
    "gain staging",
    "gain structure",
    "headroom"
   ],
   "causalExplanation": "Levels that are too high can clip at some stage; levels that are too low can leave noise relatively louder. Because many processors respond to input level, changing gain early changes how everything after it behaves.",
   "commonMisunderstanding": "That digital headroom makes gain staging irrelevant. It still changes processor behavior.",
   "domains": [
    "gainStaging",
    "clipping"
   ],
   "id": "concept.gain-staging",
   "practicalExample": "If a compressor suddenly acts much harder after you raise a clip's gain, that is gain staging changing its threshold relationship.",
   "relatedProcedureIDs": [],
   "reviewState": "reviewed",
   "simpleExplanation": "Gain staging is keeping sensible levels at every step so nothing overloads and nothing is unnecessarily quiet.",
   "sourceIDs": [
    "tracksmith-curated-concepts",
    "logic-pro-12.3-effects-guide"
   ],
   "technicalExplanation": "Fixed-threshold processors respond to absolute input level, so a gain change before them alters their behavior even if the final level is compensated. Modern floating-point mixing is forgiving internally, but converters and fixed-threshold devices are not.",
   "term": "Gain staging",
   "version": "1.0",
   "whereItMatters": [
    "Recording",
    "Any threshold-based processing"
   ]
  }
 ],
